#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"  river\thill\nvalley  "};
    std::string palabra;
    int cantidad = 0;
    while (entrada >> palabra) {
        std::cout << "<" << palabra << ">\n";
        ++cantidad;
    }
    std::cout << "Words: " << cantidad;
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"  one\n\t  two-three "};
    std::string palabra;
    int cantidad = 0;
    while (entrada >> palabra) {
        ++cantidad;
        std::cout << cantidad << ":<" << palabra << ">\n";
    }
    std::cout << "Total: " << cantidad;
    return 0;
}
